// No orphan words. After the build, bind the last two words of every block of text with a no-break space,
// so one word never sits alone on the last line. This covers headings, paragraphs, list items, definition
// text, labels, buttons and any other element. CSS `text-wrap: balance` and `pretty` (src/styles/global.css) do the rest.
// Scripts, styles, code, pre, textarea, svg and the title are left as they are.
// design.html is generated by `npm run design -- build`, so it is skipped.
import { readdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

const KEEP = /<(script|style|pre|code|textarea|svg|title)\b[\s\S]*?<\/\1>/gi;
// Two words, then the end of the text: the next thing is a closing tag.
const LAST_TWO_WORDS = /(\S+)[ \t\r\n]+([^\s<>]+)(?=<\/[a-zA-Z])/g;

export function bindLastWords(html) {
  const kept = [];
  const masked = html.replace(KEEP, (block) => `\u0000${kept.push(block) - 1}\u0000`);
  const bound = masked.replace(LAST_TWO_WORDS, (_all, a, b) => `${a}&nbsp;${b}`);
  return bound.replace(/\u0000(\d+)\u0000/g, (_all, i) => kept[Number(i)]);
}

export default function noOrphans() {
  return {
    name: "no-orphans",
    hooks: {
      "astro:build:done": async ({ dir }) => {
        const root = fileURLToPath(dir);
        for (const name of await readdir(root)) {
          if (!name.endsWith(".html") || name === "design.html") continue;
          const file = join(root, name);
          const html = await readFile(file, "utf8");
          const next = bindLastWords(html);
          if (next !== html) await writeFile(file, next);
        }
      }
    }
  };
}
